func (s *Service) cursor(ctx context.Context, name string) int64 {
	var n int64
	_ = s.db.QueryRowContext(ctx, "SELECT value FROM analytics_state WHERE name=?", name).Scan(&n)
	return n
}

func eventCost(e Event, p model.ModelPrice) int64 {
	uncached := max(int64(0), e.Tokens.Input-e.Tokens.Cached-e.Tokens.CacheCreation)
	cost := float64(uncached)*p.Prompt + float64(e.Tokens.Output)*p.Completion + float64(e.Tokens.Cached)*p.CacheRead + float64(e.Tokens.CacheCreation)*p.CacheCreation
	return int64(math.Round(cost * 1000))
}

func (s *Service) Accounts(ctx context.Context) ([]Account, error) {
	rows, err := s.db.QueryContext(ctx, "SELECT id,provider,label,auth_index,auth_file,last_seen_ms,poll_at_ms,poll_error FROM analytics_accounts ORDER BY provider,label")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []Account{}
	for rows.Next() {
		var a Account
		if err = rows.Scan(&a.ID, &a.Provider, &a.Label, &a.AuthIndex, &a.AuthFile, &a.LastSeen, &a.PollAt, &a.PollError); err != nil {
			return nil, err
		}
		out = append(out, a)
	}
	return out, rows.Err()
}
