func (s *Service) proofForValue(ctx context.Context, id string, through, observationThrough, at int64, book ComparisonPriceBook, keys ...string) (Proof, error) {
	key := optionalKey(keys)
	if at == 0 {
		at = s.at
		through = s.cursor(ctx, "events")
		_ = s.db.QueryRowContext(ctx, "SELECT coalesce(max(rowid),0) FROM analytics_observations").Scan(&observationThrough)
	}
	p := Proof{Events: []Event{}, Observations: []Observation{}, Prices: map[string]json.RawMessage{}, Policy: "Request-start attribution in [start, reset); straddles and clock skew flagged. Cached input is a subset of input; reasoning a subset of output. Cost sums frozen per-event nanodollars. Quota is provider-observed, not gateway-exclusive. Projections use deltas, not absolute utilization."}
	accounts, err := s.Accounts(ctx)
	if err != nil {
		return p, err
	}
	for _, a := range accounts {
		events, obs, err := s.evidence(ctx, a.ID, through, observationThrough)
		if err != nil {
			return p, err
		}
		for _, w := range deriveValuationWindows(a, obs, events, at, book) {
			if w.ID != id {
				continue
			}
			shared := w
			w = filterWindow(w, events, key)
			p.Window = w
			p.PollRuns = []PollRun{}
			pollStart, pollEnd := w.Start, min(at, w.AttributionEnd)
			if w.Kind == "ledger" {
				pollStart = 0
				pollEnd = at
			}
			rows, err := s.db.QueryContext(ctx, "SELECT id,observed_ms,source,status FROM analytics_poll_runs WHERE account=? AND observed_ms>=? AND observed_ms<=? ORDER BY observed_ms,id", a.ID, pollStart, pollEnd)
			if err != nil {
				return p, err
			}
			for rows.Next() {
				var run PollRun
				if err = rows.Scan(&run.ID, &run.Observed, &run.Source, &run.Status); err != nil {
					rows.Close()
					return p, err
				}
				p.PollRuns = append(p.PollRuns, run)
			}
			err = rows.Err()
			rows.Close()
			if err != nil {
				return p, err
			}
			for _, e := range events {
				if inWindow(e, w) {
					if keyMatches(e, key) {
						p.Events = append(p.Events, e)
					}
					if key != "" {
						p.SharedEvents = append(p.SharedEvents, e)
					}
					if e.PriceID != "" {
						var raw string
						if err = s.db.QueryRowContext(ctx, "SELECT payload FROM analytics_prices WHERE id=?", e.PriceID).Scan(&raw); err != nil {
							return p, err
						}
						p.Prices[e.PriceID] = json.RawMessage(raw)
					}
				} else if matches(e, w.Scope, w.Models) && e.Started < w.Reset && e.Completed >= w.Start {
					p.BoundaryEvents = append(p.BoundaryEvents, e)
				}
			}
			observationIDs := map[string]bool{}
			for _, oid := range w.ObservationIDs {
				observationIDs[oid] = true
			}
			for _, o := range obs {
				if w.Kind == "ledger" || observationIDs[o.ID] || book.Policy == profileValuePolicy && o.ClosedCycle != nil && o.ClosedCycle.WindowID == w.ID {
					p.Observations = append(p.Observations, o)
				}
			}
			var sum Tokens
			var cost int64
			for _, e := range p.Events {
				addTokens(&sum, e.Tokens)
				if e.CostNano != nil {
					cost += *e.CostNano
				}
			}
			p.Reconciled = sum == w.Tokens && cost == w.CostNano && int64(len(p.Events)) == w.Requests
			if key != "" {
				var all Tokens
				var allCost int64
				for _, e := range p.SharedEvents {
					addTokens(&all, e.Tokens)
					if e.CostNano != nil {
						allCost += *e.CostNano
					}
				}
				p.SharedReconciled = all == shared.Tokens && allCost == shared.CostNano && int64(len(p.SharedEvents)) == shared.Requests
				p.Policy += " Selected-key request totals reconcile separately from shared_events. Quota observations and capacity calibration always include all keys sharing this account pool."
			}
			return p, nil
		}
	}
	return p, sql.ErrNoRows
}
